import {PASS_NAME,PASS_PRICE,seasonMeta,seasonState,levelForXP,rewardXP,rewardFor,COSMETIC_TYPES,SEASON_QUESTS,cosmeticLook} from './season.js';
import {DAILY_QUESTS,daily,dayKey} from './progression.js';
const color=value=>/^#[0-9a-f]{6}$/i.test(value||'')?value:'#5cddff';
const icon=r=>r.kind==='gold'?'◈':r.kind==='premium'?'♛':r.type==='nick'?'Aa':r.type==='title'?'✦':r.type==='entry'?'✺':r.type==='border'?'◎':'▧';
export function passPreview(c,selection){
 const {S,esc,fmt}=c,p=S.profile,now=p?.serverNow||Date.now(),meta=seasonMeta(now),s=p?seasonState(p,now):null;
 const [lane,raw]=String(selection||'paid:5').split(':'),level=Number(raw),r=rewardFor(level,lane,meta)||rewardFor(5,'paid',meta),valid=rewardFor(level,lane,meta),key=lane+':'+level,claimed=s?.claimed.includes(key),unlocked=valid&&s&&s.xp>=rewardXP(level)&&(lane==='free'||s.paid),name=p?.name||'Oyuncu',gold=r.kind==='gold';
 return `<div class="pass-preview-cell ${r.type==='border'?'preview-'+level:''} ${r.type==='entry'?'preview-entry':''}" style="--reward-color:${color(r.color)}"><div class="pass-cell-orbit"></div><div class="pass-demo-cell"><small>${r.type==='title'?'✦ ÖNCÜ':''}</small><strong class="${r.type==='nick'?'nick-glow':''}">${esc(name)}</strong><span>12.480</span></div>${gold?`<div class="pass-floating-coin">◈<b>${fmt(r.amount)}</b></div>`:''}${r.kind==='premium'?'<div class="pass-premium-mark">♛<b>3 GÜN</b></div>':''}</div><div class="pass-detail"><small>${lane==='free'?'ÜCRETSİZ SIRA':PASS_NAME.toLocaleUpperCase('tr')} · ${level>30?'EKSTRA '+(level-30):'KADEME '+level}</small><h2>${esc(r.name)}</h2><p>${r.kind==='gold'?'Topladığında Gold bakiyene eklenir.':r.kind==='premium'?'Mevcut Premium sürene üç gün eklenir.':'Koleksiyonunda kalır. Envanterden takıp oyunda kullanabilirsin.'}</p><div class="pass-detail-status">${fmt(rewardXP(level))} XP ${claimed?'· ✓ Toplandı':unlocked?'· Toplanmaya hazır':lane==='paid'&&!s?.paid?'· ZirvePass gerekli':'· Kilitli'}</div>${!p?'<button class="pass-main-button" data-page="auth">Giriş yap</button>':`<button class="pass-main-button" data-act="claim" data-level="${level}" data-lane="${lane}" ${!unlocked||claimed?'disabled':''}>${claimed?'✓ Toplandı':unlocked?'Ödülü topla':'Kilitli'}</button>`}</div>`;
}
export function seasonPage(c,page,params={}){
 const {S,esc,fmt,empty}=c,p=S.profile,now=p?.serverNow||Date.now(),meta=seasonMeta(now),s=p?seasonState(p,now):null,level=levelForXP(s?.xp||0),look=cosmeticLook(p),xp=s?.xp||0;
 const tabs=`<nav class="pass-nav" aria-label="ZirvePass bölümleri">${[['season',PASS_NAME],['quests','Görevler'],['inventory','Envanter']].map(([id,name])=>`<button class="${page===id?'active':''}" data-page="${id}">${name}</button>`).join('')}<button class="pass-return" data-pass-return>Oyuna dön ↗</button></nav>`;
 let content='';
 if(page==='season'){
  const selection=S.passSelection||'paid:5';
  content=`<section class="pass-stage"><div class="pass-season-info"><small>SEZON ${String(meta.number).padStart(2,'0')}</small><h1>${esc(meta.title)}</h1><p data-pass-countdown="${meta.endsAt}" data-server-now="${now}" data-client-now="${Date.now()}"></p><p class="pass-muted">Her sezon yeni bir yol. Kazandığın kozmetikler kalıcı.</p>${p?`<div class="pass-account-progress"><span>KADEME <b>${level}</b> / 30</span><span>${fmt(xp)} XP</span><progress max="${xp>=6000?9000:6000}" value="${Math.min(9000,xp)}"></progress><small>${xp>=9000?'Bütün ekstra kademeler açıldı':xp>=6000?'Sonraki ekstra: '+fmt((Math.floor((xp-6000)/1000)+1)*1000+6000)+' XP':fmt(200-xp%200)+' XP sonra yeni kademe'}</small></div><button class="pass-main-button" data-act="pass" ${s.paid?'disabled':''}>${s.paid?'✓ ZirvePass etkin':fmt(PASS_PRICE)+' Gold · ZirvePass aç'}</button><button class="pass-text-button" data-act="claimAll">Hazır ödülleri birlikte topla</button>`:'<button class="pass-main-button" data-page="auth">Giriş yap · İlerlemeye başla</button>'}<p class="pass-footnote">Ücretsiz sırada 160.000 Gold; ZirvePass sırasında 800.000 ek Gold ve kozmetikler. Toplamlara ekstra kademeler dahildir.</p></div><div class="pass-preview" id="pass-preview">${passPreview(c,selection)}</div></section>
  <section class="pass-reward-zone" aria-label="Sezon ödülleri"><div class="pass-reward-heading"><div><h2>Ödül yolu</h2><small>30 kademe + 3 ekstra · Bir ödüle dokunarak önizle</small></div><div><button data-pass-scroll="-1" aria-label="Önceki ödüller">‹</button><button data-pass-scroll="1" aria-label="Sonraki ödüller">›</button></div></div><div class="pass-lane-labels"><span>ÜCRETSİZ</span><span>ZİRVE<span>PASS</span></span></div><div class="pass-reward-scroll" id="pass-reward-scroll"><div class="pass-track">${Array.from({length:33},(_,i)=>i+1).map(l=>`<div class="pass-tier"><div class="pass-tier-number ${xp>=rewardXP(l)?'unlocked':''}">${l>30?'EKSTRA '+(l-30):String(l).padStart(2,'0')}<small>${fmt(rewardXP(l))} XP</small></div>${['free','paid'].map(lane=>{const r=rewardFor(l,lane,meta);if(!r)return '<div class="pass-empty-reward" aria-label="Bu kademede ücretsiz ödül yok">—</div>';const key=lane+':'+l,claimed=s?.claimed.includes(key),ready=s&&xp>=rewardXP(l)&&(lane==='free'||s.paid)&&!claimed;return `<button aria-label="${esc(r.name)}, ${l>30?'ekstra '+(l-30):'kademe '+l}, ${lane==='free'?'ücretsiz':'ZirvePass'}" data-pass-select="${key}" class="pass-reward ${lane} ${selection===key?'selected':''} ${claimed?'claimed':ready?'ready':''}" style="--reward-color:${color(r.color)}"><i>${icon(r)}</i><strong>${r.kind==='gold'?fmt(r.amount):esc(r.name)}</strong><small>${claimed?'✓ TOPLANDI':ready?'TOPLANABİLİR':lane==='free'?'ÜCRETSİZ':s?.paid?'ZİRVE':'ZİRVEPASS'}</small><span class="pass-reward-lock">${claimed?'✓':ready?'●':'⌑'}</span></button>`}).join('')}</div>`).join('')}</div></div></section><div class="pass-benefits"><span>◈ İki ayrı ödül sırası</span><span>✦ Kalıcı koleksiyon</span><span>↗ Sonradan aç, hak edilenleri topla</span></div>`;
 }else if(page==='quests'){
  const tab=params.tab==='seasonal'?'seasonal':'daily',d=p?daily(p,now):null,qs=tab==='seasonal'?SEASON_QUESTS:DAILY_QUESTS;
  content=`<section class="pass-section-heading"><small>OYNA · GÖREV TAMAMLA · İLERLE</small><h1>Görevler</h1><p>Herkes için aynı hedefler. Günlük görevlerden 250 XP, sezonluk görevlerden toplam 6.500 XP.</p></section><div class="pass-quest-layout"><section><div class="pass-quest-tabs" role="tablist"><button role="tab" aria-selected="${tab==='daily'}" class="${tab==='daily'?'active':''}" data-page="quests" data-pass-tab="daily">Günlük</button><button role="tab" aria-selected="${tab==='seasonal'}" class="${tab==='seasonal'?'active':''}" data-page="quests" data-pass-tab="seasonal">Sezonluk</button></div><p class="pass-muted">${tab==='daily'?'Türkiye saatiyle 00.00’da yenilenir.':'Sezon boyunca bir kez tamamlanır; yeni sezonda yenilenir.'}</p><div class="pass-quest-list">${qs.map(q=>{const current=tab==='seasonal'?(s?.stats[q.metric]||0):(d?.[q.id]||0),claimed=tab==='seasonal'?s?.questClaims.includes(q.id):d?.claimed.includes(q.id),ready=current>=q.target;return `<article class="pass-quest ${claimed?'done':''}"><div class="pass-quest-icon">${claimed?'✓':q.metric==='kills'||q.id==='kills'?'✦':'◈'}</div><div><h3>${esc(q.name)}</h3><progress value="${Math.min(current,q.target)}" max="${q.target}"></progress><small>${fmt(current)} / ${fmt(q.target)}${q.gold?' · '+fmt(q.gold)+' Gold':''}</small></div><div class="pass-quest-action"><b>+${fmt(q.xp)} XP</b><button class="pass-main-button" data-act="${tab==='seasonal'?'claimSeasonQuest':'claimDaily'}" data-value="${q.id}" ${!p||!ready||claimed?'disabled':''}>${claimed?'Toplandı':ready?'Topla':'Devam ediyor'}</button></div></article>`}).join('')}</div></section><aside class="pass-progress-card"><small>SEZON ${meta.number}</small><b>${level}<span>/30</span></b><h3>${esc(meta.title)}</h3><progress max="6000" value="${Math.min(6000,xp)}"></progress><p>${fmt(xp)} XP · Son kademe 6.000 XP</p><p>Ekstra ödüller 7.000, 8.000 ve 9.000 XP’de açılır.</p>${!p?'<button class="pass-main-button" data-page="auth">Giriş yap</button>':'<button class="pass-text-button" data-page="season">Ödül yoluna dön ↗</button>'}</aside></div>`;
 }else{
  content=`<section class="pass-section-heading"><small>KOLEKSİYONUN SENİNLE KALIR</small><h1>Envanter</h1><p>Her türden bir kozmetik tak. Farklı sezonlardan kazandıklarını birlikte kullanabilirsin.</p></section><div class="pass-inventory-layout"><div>${Object.entries(COSMETIC_TYPES).map(([type,title])=>{const items=Object.values(p?.cosmetics||{}).filter(r=>r.type===type);return `<section class="pass-inventory-group"><h3>${title}<small>Takılı: ${esc(look[type]?.name||'Yok')}</small></h3><div class="pass-inventory-items"><button data-act="equipCosmetic" data-kind="${type}" data-value="" class="pass-inventory-item ${!look[type]?'equipped':''}" ${!p?'disabled':''}>◯<span>Yok</span></button>${items.map(r=>`<button data-act="equipCosmetic" data-kind="${type}" data-value="${esc(r.id)}" class="pass-inventory-item ${p.loadout[type]===r.id?'equipped':''}" style="--reward-color:${color(r.color)}"><i>${icon(r)}</i><span>${esc(r.name)}</span><small>${p.loadout[type]===r.id?'✓ TAKILI':'TAK'}</small></button>`).join('')||'<p class="pass-muted">Bu türde henüz kozmetiğin yok.</p>'}</div></section>`}).join('')}${p?.inventory.some(id=>/^neon-/.test(id))?'<section class="pass-inventory-group"><h3>Önceki koleksiyon</h3>'+p.inventory.filter(id=>/^neon-/.test(id)).map(id=>`<button class="pass-text-button" data-act="equip" data-value="${p.equipped===id?'':esc(id)}">${esc(id)} · ${p.equipped===id?'Çıkar':'Tak'}</button>`).join('')+'</section>':''}</div><aside class="pass-inventory-preview" style="--reward-color:${color(look.nick?.color||look.border?.color)}"><div class="pass-demo-cell ${look.nick?'nick-glow':''} ${look.border?'has-border':''}"><small>${esc(look.title?.name||'')}</small><strong>${esc(p?.name||'Oyuncu')}</strong><span>12.480</span></div><h3>Oyun içi görünüm</h3>${Object.entries(COSMETIC_TYPES).map(([type,title])=>`<p>${title}<b>${esc(look[type]?.name||'Yok')}</b></p>`).join('')}<button class="pass-main-button" data-pass-entry-preview>Girişi önizle</button><div id="pass-entry-preview" aria-live="polite"></div></aside></div>`;
 }
 return `<div class="zirve-pass ${look.theme?'has-ion-theme':''}">${tabs}${!S.online?'<div class="pass-training-note">ANTRENMAN · Bu profildeki ilerleme yalnızca bu tarayıcıda saklanır.</div>':''}${content}<footer class="pass-footer">ZirvePass · Sezon ${meta.number} · Kozmetikler envanterinde kalır. Sezon XP’si ve bilet yeni sezonda yenilenir.</footer></div>`;
}
